import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        boolean[][] pacific = new boolean[rows][cols];
        boolean[][] atlantic = new boolean[rows][cols];

        for (int row = 0; row < rows; row++) {
            dfs(heights, pacific, row, 0);
            dfs(heights, atlantic, row, cols - 1);
        }
        for (int col = 0; col < cols; col++) {
            dfs(heights, pacific, 0, col);
            dfs(heights, atlantic, rows - 1, col);
        }

        return collectBoth(pacific, atlantic);
    }

    private void dfs(int[][] heights, boolean[][] visited, int row, int col) {
        if (visited[row][col]) {
            return;
        }
        visited[row][col] = true;
        for (int[] direction : DIRECTIONS) {
            int nextRow = row + direction[0];
            int nextCol = col + direction[1];
            if (nextRow < 0 || nextRow >= heights.length || nextCol < 0 || nextCol >= heights[0].length) {
                continue;
            }
            if (heights[nextRow][nextCol] < heights[row][col]) {
                continue;
            }
            dfs(heights, visited, nextRow, nextCol);
        }
    }

    private List<List<Integer>> collectBoth(boolean[][] pacific, boolean[][] atlantic) {
        List<List<Integer>> result = new ArrayList<>();
        for (int row = 0; row < pacific.length; row++) {
            for (int col = 0; col < pacific[0].length; col++) {
                if (pacific[row][col] && atlantic[row][col]) {
                    result.add(Arrays.asList(row, col));
                }
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        boolean[][] pacific = new boolean[rows][cols];
        boolean[][] atlantic = new boolean[rows][cols];
        Queue<int[]> pacificQueue = new ArrayDeque<>();
        Queue<int[]> atlanticQueue = new ArrayDeque<>();

        for (int row = 0; row < rows; row++) {
            addBorderCell(pacificQueue, pacific, row, 0);
            addBorderCell(atlanticQueue, atlantic, row, cols - 1);
        }
        for (int col = 0; col < cols; col++) {
            addBorderCell(pacificQueue, pacific, 0, col);
            addBorderCell(atlanticQueue, atlantic, rows - 1, col);
        }

        bfs(heights, pacificQueue, pacific);
        bfs(heights, atlanticQueue, atlantic);
        return collectBoth(pacific, atlantic);
    }

    private void addBorderCell(Queue<int[]> queue, boolean[][] visited, int row, int col) {
        if (!visited[row][col]) {
            visited[row][col] = true;
            queue.offer(new int[]{row, col});
        }
    }

    private void bfs(int[][] heights, Queue<int[]> queue, boolean[][] visited) {
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int row = cell[0];
            int col = cell[1];
            for (int[] direction : DIRECTIONS) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];
                if (nextRow < 0 || nextRow >= heights.length || nextCol < 0 || nextCol >= heights[0].length) {
                    continue;
                }
                if (visited[nextRow][nextCol] || heights[nextRow][nextCol] < heights[row][col]) {
                    continue;
                }
                visited[nextRow][nextCol] = true;
                queue.offer(new int[]{nextRow, nextCol});
            }
        }
    }

    private List<List<Integer>> collectBoth(boolean[][] pacific, boolean[][] atlantic) {
        List<List<Integer>> result = new ArrayList<>();
        for (int row = 0; row < pacific.length; row++) {
            for (int col = 0; col < pacific[0].length; col++) {
                if (pacific[row][col] && atlantic[row][col]) {
                    result.add(Arrays.asList(row, col));
                }
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private static final int PACIFIC = 1;
    private static final int ATLANTIC = 2;
    private static final int BOTH = PACIFIC | ATLANTIC;
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        int[][] reach = new int[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        for (int row = 0; row < rows; row++) {
            seed(reach, queue, row, 0, PACIFIC);
            seed(reach, queue, row, cols - 1, ATLANTIC);
        }
        for (int col = 0; col < cols; col++) {
            seed(reach, queue, 0, col, PACIFIC);
            seed(reach, queue, rows - 1, col, ATLANTIC);
        }

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int row = state[0];
            int col = state[1];
            int ocean = state[2];
            for (int[] direction : DIRECTIONS) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];
                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                    continue;
                }
                if (heights[nextRow][nextCol] < heights[row][col]) {
                    continue;
                }
                if ((reach[nextRow][nextCol] & ocean) != 0) {
                    continue;
                }
                reach[nextRow][nextCol] |= ocean;
                queue.offer(new int[]{nextRow, nextCol, ocean});
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (reach[row][col] == BOTH) {
                    result.add(Arrays.asList(row, col));
                }
            }
        }
        return result;
    }

    private void seed(int[][] reach, Queue<int[]> queue, int row, int col, int ocean) {
        if ((reach[row][col] & ocean) == 0) {
            reach[row][col] |= ocean;
            queue.offer(new int[]{row, col, ocean});
        }
    }
}

import java.util.*;

class Solution {
    private static final int PACIFIC = 1;
    private static final int ATLANTIC = 2;
    private static final int BOTH = PACIFIC | ATLANTIC;
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        int[][] reach = new int[rows][cols];

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (row == 0 || col == 0) {
                    reach[row][col] |= PACIFIC;
                }
                if (row == rows - 1 || col == cols - 1) {
                    reach[row][col] |= ATLANTIC;
                }
            }
        }

        boolean changed = true;
        while (changed) {
            changed = false;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    int mask = reach[row][col];
                    for (int[] direction : DIRECTIONS) {
                        int nextRow = row + direction[0];
                        int nextCol = col + direction[1];
                        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                            continue;
                        }
                        if (heights[nextRow][nextCol] <= heights[row][col]) {
                            mask |= reach[nextRow][nextCol];
                        }
                    }
                    if (mask != reach[row][col]) {
                        reach[row][col] = mask;
                        changed = true;
                    }
                }
            }
        }

        List<List<Integer>> result = new ArrayList<>();
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (reach[row][col] == BOTH) {
                    result.add(Arrays.asList(row, col));
                }
            }
        }
        return result;
    }
}
